using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;namespace RockPro{public static class LatchInProcess{public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};var r=new Dictionary<string,object>();IZDoc d=null;try{var q=(Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));dynamic l=Marshal.GetActiveObject("IronCAD.Application");var a=(IZBaseApp)l.ZIronCADApp;if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Host changed");bool already;d=a.OpenFile2((string)q["source"],false,true,out already);if(already){d=null;throw new Exception("Already open");}var s=(IZSceneDoc)d;var u=(IZSceneDocUtility)s;var data=new List<object>();foreach(int id in new[]{8838,11355,11589}){var e=(IZSceneElement)u.GetElementById(id);var mgr=e.ParameterMgr;var ps=Enumerable.Range(0,mgr.Count).Select(i=>mgr.GetParameter(i)).Select(p=>new{name=p.Name,expression=p.Expression,value=p.Value,type=p.Type.ToString()}).ToArray();var values=new List<object>();foreach(string exp in new[]{"(2 - 1)/2*532 mm","(0-(2-1)/2)*532 mm*2/(2+ABS(2-2))","IF(1,-266 mm,0 mm)","IF(2 == 1, 0 mm, -266 mm)","IF(Parent\\Parent\\Params\\RP_UchwytyKorpusLewa_Liczba == 1, 0 mm, -266 mm)","-266 mm"}){var p=mgr.GetParameterByName("RP_QWorldY");double value=0;bool valid;var errors=a.Utility.CreateEmptyIUnknownArray();p.TryToSetExpression(exp,ref value,errors,out valid);p.Expression=exp;values.Add(new{expression=exp,value=value,valid=valid,stored=p.Expression,actual=p.Value});}data.Add(new{id=id,name=((IZElement)e).Name,parameters=ps,position=Enumerable.Range(0,6).Select(k=>e.get_PositionTransformComponentExpression((eZTransformComponentType)k)).ToArray(),trials=values});}r["rows"]=data;r["scene_params"]=Enumerable.Range(0,s.ParameterMgr.Count).Select(i=>s.ParameterMgr.GetParameter(i)).Where(p=>p.Name.Contains("Liczba")||p.Name.Contains("Rozstaw")).Select(p=>new{name=p.Name,expression=p.Expression,value=p.Value,type=p.Type.ToString()}).ToArray();r["passed"]=true;}catch(Exception e){r["error"]=e.ToString();r["passed"]=false;}finally{if(d!=null)d.Close2(true);}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(r));return(bool)r["passed"]?0:1;}}}